css:
.etims-invoice { font-family: -apple-system, "Segoe UI", Roboto, sans-serif; font-size: 12px; }
.etims-invoice table { width: 100%; border-collapse: collapse; }
.etims-invoice .table-bordered th,
.etims-invoice .table-bordered td { border: 1px solid #d1d5db; padding: 4px 6px; }
.etims-invoice thead th { background: #f3f4f6; }
